 void ChooseLocation(bool useDefault){
  if(!primarySelection)return;string chosen;
  if(useDefault)chosen=AppPaths.DefaultSettings();else using(var d=new SaveFileDialog{Filter=UiText.Get("Настройки JSON (*.json)|*.json"),FileName="settings.json",InitialDirectory=Path.GetDirectoryName(path),OverwritePrompt=false,Title=UiText.Get("Выбрать основной файл настроек")}){if(d.ShowDialog()!=DialogResult.OK)return;chosen=d.FileName;}
  bool existing=File.Exists(chosen);string question=existing?UiText.Get("Загрузить настройки из выбранного файла? Он не будет перезаписан. Несохранённые изменения в окне будут заменены."):UiText.Get("Создать основной файл с текущими настройками? Пути приложений будут сохранены абсолютными, чтобы перенос не менял их смысл.");
  if(MessageBox.Show(question,UiText.Get("Файл настроек"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
  SelectSettingsLocation(chosen,existing);
 }
 public bool SelectSettingsLocation(string chosen,bool loadExisting){
  if(!primarySelection)return false;
  try{
   if(learnGate!=null)throw new IOException(UiText.Get("Сначала завершите или отмените обучение."));
   chosen=ConfigLocation.CheckSettingsPath(chosen);ConfigLocation.CheckDistinct(locatorFile,chosen);
   RemoteConfig next;
   if(File.Exists(chosen)){if(!loadExisting)return false;next=RemoteConfig.Load(chosen);}else{
    StoreEditor();next=RemoteConfig.Parse(config.Json());next.Relocate(path);ConfigLocation.CreateSettings(chosen,next);
   }
   ConfigLocation.Commit(locatorFile,chosen);path=chosen;config=next;locationBlocked=false;locationDisplay.Text=AppPaths.Display(path);RefreshCatalog("Home");status.Text=UiText.Get("Основной файл выбран: ")+AppPaths.Display(path)+UiText.Get(". Обработчик подхватит его автоматически.");return true;
  }catch(Exception ex){status.Text=UiText.Get("Выбор основного файла не завершён: ")+ex.Message;return false;}
 }
 public bool SaveCurrent(){CancelShortcutRecording();try{if(primarySelection&&!locationBlocked){string warning;string active=AppPaths.SettingsWithLocator(new string[0],locatorFile,out warning);if(!String.IsNullOrEmpty(warning)){locationBlocked=true;throw new IOException(warning);}if(!String.Equals(active,path,StringComparison.OrdinalIgnoreCase))throw new IOException(UiText.Get("Основной файл изменён в другом окне. Откройте настройки заново или выберите файл через Изменить…."));}if(locationBlocked)throw new IOException(UiText.Get("Файл настроек не выбран: исправьте указатель через Изменить… или По умолчанию."));StoreEditor();config.Save(path);status.Text=UiText.Get("Сохранено в ")+AppPaths.Display(path)+" · "+DateTime.Now.ToString("HH:mm:ss");return true;}catch(Exception ex){status.Text=UiText.Get("Не сохранено: ")+ex.Message;return false;}}
 void RefreshCatalog(string name){loading=true;buttons.Items.Clear();foreach(string n in config.Buttons.Keys)buttons.Items.Add(n);selected=config.Buttons.ContainsKey(name)?name:"Home";buttons.SelectedItem=selected;loading=false;LoadEditor();}
 public bool RemoveButton(string name){if(Array.IndexOf(RemoteConfig.Names,name)>=0||!config.Buttons.ContainsKey(name))return false;StoreEditor();config.Buttons.Remove(name);RefreshCatalog("Home");status.Text=UiText.Get("Кнопка удалена; нажмите Сохранить.");return true;}
 public bool BeginLearning(bool register){if(learnGate!=null)return false;CancelShortcutRecording();capturedKey=Keys.None;try{StoreEditor();config.Validate();learnGate=new LearnGate();learnedUsage=0;learnedInput=null;if(register){ConsumerInput.Register(Handle,false);rawRegistered=true;}learnButton.Text=UiText.Get("Отмена обучения");status.Text=UiText.Get("Нажмите одну кнопку на пульте — ожидание 30 секунд. Обработчик v2 временно приостановлен.");learnTimer=new Timer{Interval=30000};learnTimer.Tick+=(s,e)=>ExpireLearning();learnTimer.Start();return true;}catch(Exception ex){CancelLearning();status.Text=ex.Message;return false;}}
 public bool AcceptLearnReport(string device,byte[] report){int u=ConsumerInput.Decode(device,report);return u>0&&AcceptLearnInput(device,new RemoteInputEvent{InputType="Consumer",Code=(ushort)u});}
 public bool AcceptLearnInput(string device,RemoteInputEvent input){
  if(learnGate==null||learnedUsage!=0||!ConsumerInput.IsTarget(device)||input==null||input.IsRelease||input.Code==0||(input.InputType!="Consumer"&&input.InputType!="Keyboard"))return false;
  learnedUsage=input.Code;learnedInput=input;learnTimer.Stop();
  foreach(var e in config.Buttons)if(e.Value.InputType==input.InputType&&e.Value.Usage==input.Code){string n=e.Key,description=SignalDescription(input);CancelLearning();SelectButton(n);status.Text=description+UiText.Get(" · Кнопка уже есть: ")+n+UiText.Get(". Дубликат не добавлен.");return true;}
  status.Text=SignalDescription(input)+UiText.Get("; подтвердите имя. До подтверждения файл не изменён.");return true;
 }
 public bool ConfirmLearned(string name){if(learnGate==null||learnedUsage==0)return false;name=(name??"").Trim();try{var copy=RemoteConfig.Parse(config.Json());copy.Buttons.Add(name,new ButtonConfig{Scope="Global",Usage=learnedUsage,InputType=learnedInput.InputType,ScanCode=learnedInput.ScanCode,ScanFlags=learnedInput.ScanFlags});copy.Validate();config=copy;CancelLearning();RefreshCatalog(name);status.Text=UiText.Get("Добавлено без действия; выберите действие и Сохранить. Нативное действие Windows может остаться.");return true;}catch(Exception ex){status.Text=ex.Message;return false;}}
 public void CancelLearning(){if(learnTimer!=null){learnTimer.Stop();learnTimer.Dispose();learnTimer=null;}try{if(rawRegistered)ConsumerInput.Register(IntPtr.Zero,true);}finally{rawRegistered=false;if(learnGate!=null){learnGate.Dispose();learnGate=null;}}learnedUsage=0;learnedInput=null;if(learnButton!=null)learnButton.Text=UiText.Get("Добавить кнопку");}
 public void ExpireLearning(){CancelLearning();status.Text=UiText.Get("Событий за 30 секунд нет. Если кнопка не передаёт поддерживаемое Bluetooth-событие, добавить её нельзя. Попробуйте ещё раз.");}
 public Form CreateLearnDialog(){
  if(learnGate==null||learnedInput==null)return null;
  var d=new Form{Icon=Icon,Text=UiText.Get("Имя новой кнопки — ")+LearnedDescription,Font=Font,Size=new Size(530,230),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,AutoScaleMode=AutoScaleMode.None};
  var content=new Panel{Dock=DockStyle.Fill,AutoScroll=true};d.Controls.Add(content);
  content.Controls.Add(new Label{Location=new Point(16,10),Size=new Size(330,32),Text=LearnedDescription});
  var t=new TextBox{Location=new Point(16,45),Width=485,MaxLength=48,Text="",AccessibleName=UiText.Get("Имя кнопки на пульте")};content.Controls.Add(t);
  content.Controls.Add(new Label{Location=new Point(16,82),Size=new Size(485,55),Font=new Font("Segoe UI",9),Text=UiText.Get("Введите имя кнопки на пульте, например: 1. Некоторые кнопки пульта также выполняют штатное действие Windows. Назначение в этой программе не отменяет его.")});
  var diagnostic=new LinkLabel{Text=UiText.Get("Диагностика"),AutoSize=true,Location=new Point(380,16),Font=new Font("Segoe UI",9)};diagnostic.LinkClicked+=(s,e)=>MessageBox.Show(learnedInput==null?"":learnedInput.Description,UiText.Get("Диагностика сигнала"));content.Controls.Add(diagnostic);
  var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=54,Padding=new Padding(16,0,0,0),AutoScroll=true,WrapContents=false};d.Controls.Add(footer);
  var ok=Button(UiText.Get("Добавить"),(s,e)=>{if(ConfirmLearned(t.Text))d.DialogResult=DialogResult.OK;else MessageBox.Show(status.Text,"RockTek");});footer.Controls.Add(ok);
  var cancel=Button(UiText.Get("Отмена"),(s,e)=>d.DialogResult=DialogResult.Cancel);footer.Controls.Add(cancel);d.AcceptButton=ok;d.CancelButton=cancel;
  PaintTheme(d,dark.Checked);WindowLayout.ScaleAndFit(d,this);d.Shown+=(s,e)=>WindowLayout.Clamp(d);return d;
 }
 void PromptName(){if(learnGate==null||learnedInput==null)return;using(var d=CreateLearnDialog())d.ShowDialog(this);if(learnGate!=null)CancelLearning();}
 protected override void WndProc(ref Message m){if(m.Msg==0xFF&&learnGate!=null){try{ConsumerInput.ReadEvents(m.LParam,(dev,input)=>{if(AcceptLearnInput(dev,input)&&learnGate!=null){BeginInvoke(new Action(PromptName));}});}catch(Exception ex){CancelLearning();status.Text=UiText.Get("Ошибка обучения: ")+ex.Message;}}base.WndProc(ref m);}
 protected override void Dispose(bool disposing){if(disposing){CancelShortcutRecording();capturedKey=Keys.None;CancelLearning();}base.Dispose(disposing);if(disposing&&ownedIcon!=null){ownedIcon.Dispose();ownedIcon=null;}}
 void Import(){using(var d=new OpenFileDialog{Filter="JSON (*.json)|*.json"})if(d.ShowDialog()==DialogResult.OK)try{ImportSettings(d.FileName);status.Text=UiText.Get("Импортировано; нажмите Сохранить для записи в ")+AppPaths.Display(path);}catch(Exception ex){status.Text=ex.Message;}}
 void Export(){using(var d=new SaveFileDialog{Filter="JSON (*.json)|*.json",FileName="settings.json"})if(d.ShowDialog()==DialogResult.OK)try{StoreEditor();var copy=RemoteConfig.Parse(config.Json());copy.Relocate(path);copy.Save(d.FileName);status.Text=UiText.Get("Экспорт: ")+d.FileName;}catch(Exception ex){status.Text=ex.Message;}}
}
public static class AppPaths {
 public static string Display(string path){foreach(string variable in new[]{"OneDriveConsumer","OneDrive","LOCALAPPDATA","USERPROFILE"}){string root=Environment.GetEnvironmentVariable(variable);if(!String.IsNullOrEmpty(root)&&path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return "%"+(variable=="OneDriveConsumer"?"OneDrive":variable)+"%"+path.Substring(root.Length);}return path;}
 public static bool IsExplicit(string[] args){return Array.IndexOf(args,"--config")>=0;}
 public static string DefaultSettings(){string one=Environment.GetEnvironmentVariable("OneDriveConsumer");if(String.IsNullOrEmpty(one))one=Environment.GetEnvironmentVariable("OneDrive");if(String.IsNullOrEmpty(one)){string candidate=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"OneDrive");if(Directory.Exists(candidate))one=candidate;}return Path.Combine(String.IsNullOrEmpty(one)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RockTekRemote"):Path.Combine(one,"RockTekRemote"),"settings.json");}
 public static string Settings(string[] args){string warning;return Settings(args,out warning);}
 public static string Settings(string[] args,out string warning){return SettingsWithLocator(args,ConfigLocation.DefaultFile,out warning);}
 public static string SettingsWithLocator(string[] args,string locator,out string warning){
  warning="";for(int i=0;i<args.Length;i++)if(args[i]=="--config"){if(i+1>=args.Length)throw new ArgumentException(UiText.Get("--config: укажите файл."));return ConfigLocation.CheckSettingsPath(Path.GetFullPath(args[i+1]));}
  try{string selected=ConfigLocation.Read(locator);if(selected!=null)return selected;}catch(Exception e){warning=UiText.Get("Файл настроек: указатель недоступен или повреждён. ")+e.Message+UiText.Get(" Выберите файл через Изменить…; сохранение заблокировано до выбора.");}
  return ConfigLocation.CheckSettingsPath(DefaultSettings());
 }
 public static string Player(RemoteConfig c,string settings){if(String.IsNullOrWhiteSpace(c.TargetApplicationPath))throw new ArgumentException(UiText.Get("Выберите целевое приложение .exe в настройках."));return ActionValidation.ResolvePath(c.TargetApplicationPath,settings);}
}
